import{_ as a,c as e,a2 as t,o as r}from"./chunks/framework.CqbvlPrP.js";const c=JSON.parse('{"title":"清心诀、冰心诀、静心诀、定心心经、养神诀","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/清心诀、冰心诀、静心诀、定心心经、养神诀.md","filePath":"meditation/清心诀、冰心诀、静心诀、定心心经、养神诀.md"}'),o={name:"meditation/清心诀、冰心诀、静心诀、定心心经、养神诀.md"};function i(n,p,h,l,d,s){return r(),e("div",null,p[0]||(p[0]=[t('<h1 id="清心诀、冰心诀、静心诀、定心心经、养神诀" tabindex="-1">清心诀、冰心诀、静心诀、定心心经、养神诀 <a class="header-anchor" href="#清心诀、冰心诀、静心诀、定心心经、养神诀" aria-label="Permalink to &quot;清心诀、冰心诀、静心诀、定心心经、养神诀&quot;">​</a></h1><h2 id="《清心诀》" tabindex="-1">《清心诀》 <a class="header-anchor" href="#《清心诀》" aria-label="Permalink to &quot;《清心诀》&quot;">​</a></h2><p>清心如水，清水即心；</p><p>微风无起，波澜不惊；</p><p>幽篁独坐，长啸鸣琴；</p><p>禅寂入定，毒龙遁形；</p><p>我心无窍，天道酬勤；</p><p>我义凛然，鬼魅皆惊；</p><p>我情豪溢，天地归心；</p><p>我志扬迈，水起风生；</p><p>天高地阔，流水行云；</p><p>清新治本，直道谋身；</p><p>至性至善，大道天成。</p><h2 id="《冰心诀》" tabindex="-1">《冰心诀》 <a class="header-anchor" href="#《冰心诀》" aria-label="Permalink to &quot;《冰心诀》&quot;">​</a></h2><p>心若冰清，天塌不惊；</p><p>万变犹定，神怡气静；</p><p>尘垢不沾，俗相不染；</p><p>虚空甯宓，浑然无物；</p><p>无有相生，难易相成；</p><p>份与物忘，同乎浑涅；</p><p>天地无涯，万物齐一；</p><p>飞花落叶，虚怀若谷；</p><p>千般烦忧，才下心头；</p><p>即展眉头，灵台清幽；</p><p>心无罣碍，意无所执；</p><p>解心释神，莫然无魂；</p><p>水流心不惊，云在意俱迟；</p><p>一心不赘物，古今自逍遥。</p><h2 id="《静心诀》" tabindex="-1">《静心诀》 <a class="header-anchor" href="#《静心诀》" aria-label="Permalink to &quot;《静心诀》&quot;">​</a></h2><p>冰寒千古，万物尤静；</p><p>心宜气静，望我独神；</p><p>心神合一，气宜相随；</p><p>相间若余，万变不惊；</p><p>无痴无嗔，无欲无求；</p><p>无舍无弃，无为无我。</p><h2 id="《定心心经》" tabindex="-1">《定心心经》 <a class="header-anchor" href="#《定心心经》" aria-label="Permalink to &quot;《定心心经》&quot;">​</a></h2><p>心若冰清，天塌不惊；</p><p>万变犹定，神怡气静；</p><p>忘我守一，六根大定；</p><p>戒点养气，无私无为；</p><p>上下相顾，神色相依；</p><p>蓄意玄关，降伏思虑；</p><p>内外无物，心神净明。</p><h2 id="《养神诀》" tabindex="-1">《养神诀》 <a class="header-anchor" href="#《养神诀》" aria-label="Permalink to &quot;《养神诀》&quot;">​</a></h2><p>神为心所主，养神必先养心。</p><p>心静则神安，心动则神疲。</p><p>心为神所主，养心必先养神。</p><p>神安则心静，心动则神疲。</p><hr><p>神，指心力、心劲。神是身体之主、生死之本、善恶之源。要做到主动养精气，应保持精神愉快，心情舒畅，遇事不怒，思想宽广，饮食有节，起居正常，劳逸结合，锻炼至上，增强抵抗力。</p><p>《内经》 云: &quot;精不足者，补之以味。’ 浓郁之味，不能生精;惟清淡之味，乃能补精也。万物皆有味，调和胜则真味衰矣。淡煮之得法，自有一段冲和恬澹之味，益人肠胃。故淡食 可以养精，可以益寿。</p><p>《七部语要》说:“神静则心和，心和而神全。神躁则心荡，心荡则神伤。将全其形，先在理神。故恬和养神，则自安于内;清虚栖心，则不诱于外也。七窍者，精神之户牖也; 志气者，五脏之使候也。耳目诱于声色，鼻口悦于芳菲，肌体舒于安适，则精神弛而不守: 志卸于趋舍，则五脏滔荡而不安。嗜欲连绵于外，心脏壅塞于内，曼衍于荒淫之波，留连 于是非之境，而不败德伤生者，盖亦寡矣，以劳形而伤神也。</p>',52)]))}const m=a(o,[["render",i]]);export{c as __pageData,m as default};
